mapper.select:
SELECT * FROM tb_srm_asn
WHERE supplier_id = #{supplierId}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE tb_srm_asn
SET order_detail_id = #{orderDetailId}, ship_qty = #{shipQty}, ship_date = #{shipDate},
    actual_eta_date = #{actualEtaDate}, warehouse_in_no = #{warehouseInNo}
WHERE id = #{asnId}

UPDATE tb_srm_asn
SET ship_qty = #{shippedQty}, ship_date = #{shipDate},
    actual_eta_date = #{actualEtaDate}, warehouse_in_no = #{warehouseInNo}
WHERE id = #{asnId}

mapper.select:
SELECT COALESCE(MAX(CAST(SUBSTRING(asn_no, -4) AS UNSIGNED)), 0)
FROM tb_srm_asn
WHERE supplier_id = #{supplierId} AND ship_date = #{shipDate}

mapper.delete:
DELETE FROM tb_srm_asn
WHERE supplier_id = #{supplierId} AND ship_date = #{shipDate}
  AND ship_qty = 0 AND status = 'CREATED' AND asn_no IS NOT NULL
